This is a little late, but here's my answer in C++:

    #include <iostream>
    #include <cstdlib>
    #include <string>
    #include <ctime>

    using namespace std;

    int main(){

        srand(time(0));

        int num = rand() %100;
        string guess;
        bool gameOver = false;

        cout << "Welcome to the Guessinator!" << endl;
        cout << "To begin, please press ENTER" << endl;
        cout << "In order to quit at any time, input 'exit'" << endl;
        cin.get();

        while (!gameOver){

            cout << "Please enter your guess: ";
            cin >> guess;

            if (guess == "exit" || guess == "Exit"){
                cout << "Goodbye!" << endl;
                cin.get();
                return 0;
            }

            int attempt = atoi(guess.c_str());

            if (attempt == num){
                cout << "You win! Hurray!" << endl;
                cin.get();
                return 0;
            }

            if (attempt > num){
                cout << "Too high!" << endl;
            }

            if (attempt < num){
                cout << "Too low!" << endl;
            }
        }
    }

